import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;
import java.util.stream.IntStream;

public class VirtualThreadDemo {
    public static void main(String[] args) throws InterruptedException {
        // 1. Using Thread.ofVirtual()
        Thread customVirtualThread = Thread.ofVirtual()
                .name("worker-vthread-", 0)
                .unstarted(() -> System.out.println("Running custom virtual thread: " + Thread.currentThread()));
        customVirtualThread.start();
        customVirtualThread.join();

        // 2. Using Executors.newVirtualThreadPerTaskExecutor()
        try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10).forEach(i -> {
                executor.submit(() -> {
                    Thread.sleep(Duration.ofMillis(100));
                    System.out.println("Task " + i + " executed by: " + Thread.currentThread());
                    return i;
                });
            });
        } // ExecutorService closes automatically, awaiting termination of all tasks
    }
}
